// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(this) && sender != address(0));

        // Test that only owner can call withdrawAll without reverting
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", sender));

        // The rule: the call reverts for non-owner callers (msg.sender != owner)
        assertTrue(!success, "Non-owner should not be able to withdraw");
    }
}
